    "micro":        { "family": "Inter",  "weight": 400, "size": 10, "lineHeight": "auto",  "tailwind": "text-[10px] font-normal" },
    "micro-med":    { "family": "Inter",  "weight": 500, "size": 10, "lineHeight": 14.5,    "tailwind": "text-[10px] font-medium leading-[14.5px]" },
